/**
 * Imagens oficiais do modelo PAS_MODELO_2026 em formato Base64 para incorporação nativa em DOCX e PDF.
 */

export const IMAGE_BRASAO_GOVERNO_B64 = "data:image/jpeg;base64,";
export const IMAGE_LOGO_ESCOLA_B64 = "data:image/png;base64,";

export function getBrasaoGovernoBuffer(): Uint8Array {
  const binaryString = atob("");
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export function getLogoEscolaBuffer(): Uint8Array {
  const binaryString = atob("");
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}
